import React, { useEffect, useState } from 'react';
import axios from 'axios';

function App() {
  const [categories, setCategories] = useState([]);

  useEffect(() => {
    axios.get('http://127.0.0.1:8000/api/categories/')
      .then(res => setCategories(res.data))
      .catch(err => console.log(err));
  }, []);

  return (
    <div className="min-h-screen bg-gray-100">
      {/* Navbar */}
      <nav className="bg-orange-600 p-4 text-white shadow-lg">
        <h1 className="text-2xl font-bold text-center">🍕 Presto Restau</h1>
      </nav>

      {/* Hero Section */}
      <div className="p-8 text-center bg-white border-b">
        <h2 className="text-4xl font-extrabold text-gray-800">Merhba bikom!</h2>
        <p className="text-gray-600 mt-2 text-lg">Ahssen pizzas o tacos f-l-mdina</p>
      </div>

      {/* Menu Grid */}
      <div className="max-w-6xl mx-auto p-6 grid grid-cols-1 md:grid-cols-3 gap-6">
        {categories.map(cat => (
          cat.dishes.map(dish => (
            <div key={dish.id} className="bg-white rounded-2xl shadow-md overflow-hidden hover:shadow-xl transition">
              <div className="h-40 bg-orange-100 flex items-center justify-center">
                <span className="text-5xl">🍔</span>
              </div>
              <div className="p-4">
                <div className="flex justify-between items-center">
                  <h3 className="text-xl font-bold text-gray-800">{dish.name}</h3>
                  <span className="text-orange-600 font-bold">{dish.price} DH</span>
                </div>
                <p className="text-sm text-gray-500 mt-1">{cat.name}</p>
                <button className="w-full mt-4 bg-gray-900 text-white py-2 rounded-xl font-bold hover:bg-orange-600 transition">
                  Commander
                </button>
              </div>
            </div>
          ))
        ))}
      </div>
    </div>
  );
}

export default App;
